'use strict';

// MODULES //

var Linter = require( 'eslint' ).Linter;
var parseJSDoc = require( 'doctrine' ).parse;
var isObject = require( '@stdlib/assert/is-object' );
var objectKeys = require( '@stdlib/utils/keys' );
var contains = require( '@stdlib/assert/contains' );
var replace = require( '@stdlib/string/replace' );
var format = require( '@stdlib/string/format' );
var findJSDoc = require( '@stdlib/_tools/eslint/utils/find-jsdoc' );


// VARIABLES //

var RE_MODULE_TAG = /\* @module[^\n]*/g;
var DOPTS = {
	'sloppy': true,
	'unwrap': true,
	'tags': [ 'example' ],
	'lineNumbers': true
};
var linter = new Linter();
var rule;


// FUNCTIONS //

/**
* Rule for linting JavaScript code in JSDoc example blocks using ESLint.
*
* @param {Object} context - ESLint context
* @returns {Object} validators
*/
function main( context ) {
	var source;
	var config;
	var opts;

	source = context.sourceCode;

	// Build linter configuration from the provided rules:
	opts = context.options[ 0 ];
	if ( !isObject( opts ) || !isObject( opts.rules ) || objectKeys( opts.rules ).length === 0 ) {
		return {};
	}
	config = {
		'rules': opts.rules
	};

	/**
	* Checks JavaScript code in JSDoc example blocks for lint violations.
	*
	* @private
	* @param {ASTNode} node - AST node
	*/
	function validate( node ) {
		var wrapped;
		var jsdoc;
		var tags;
		var tag;
		var ast;
		var j;

		if ( node.parent.type !== 'Program' ) {
			return;
		}
		jsdoc = findJSDoc( source, node );
		if ( isObject( jsdoc ) ) {
			if ( contains( jsdoc.value, '@module' ) ) {
				wrapped = '/**' + jsdoc.value + '*/';
				wrapped = replace( wrapped, RE_MODULE_TAG, '*' );
				ast = parseJSDoc( wrapped, DOPTS );
			} else {
				ast = parseJSDoc( jsdoc.value, DOPTS );
			}
			tags = ast.tags;
			for ( j = 0; j < tags.length; j++ ) {
				tag = tags[ j ];
				if ( tag.title === 'example' && tag.description ) {
					lintExample( jsdoc, tag );
				}
			}
		}
	}

	/**
	* Lints an example code block and reports violations.
	*
	* @private
	* @param {Object} jsdoc - JSDoc comment token
	* @param {Object} tag - doctrine tag object with description and lineNumber
	*/
	function lintExample( jsdoc, tag ) {
		var violations;
		var sourceLine;
		var msg;
		var v;
		var i;

		violations = linter.verify( tag.description, config );
		for ( i = 0; i < violations.length; i++ ) {
			v = violations[ i ];

			// Skip fatal parse errors (syntax errors in example code):
			if ( v.fatal ) {
				continue;
			}
			sourceLine = jsdoc.loc.start.line + tag.lineNumber + v.line;
			msg = format( '%s (%s)', v.message, v.ruleId );
			context.report({
				'node': null,
				'loc': {
					'start': {
						'line': sourceLine,
						'column': 0
					}
				},
				'message': msg
			});
		}
	}

	return {
		'FunctionDeclaration': validate,
		'FunctionExpression:exit': validate,
		'VariableDeclaration': validate,
		'ExpressionStatement': validate
	};
}


// MAIN //

rule = {
	'meta': {
		'type': 'suggestion',
		'docs': {
			'description': 'lint JavaScript code in JSDoc example blocks using ESLint'
		},
		'schema': [
			{
				'type': 'object',
				'properties': {
					'rules': {
						'type': 'object'
					}
				},
				'additionalProperties': false
			}
		]
	},
	'create': main
};


// EXPORTS //

module.exports = rule;
